function setup() {
  createCanvas(windowWidth, windowHeight);
  try {
    img = loadImage("file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/rain.png");
  } catch(e) {}
  imageMode(CENTER);
  noStroke();
  background(255,2);

